// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(new __InvMutHandleStub()), address(new __InvMutHandleStub())); }

    function testFuzz_property(address newOwner) public {
        // admissible domain: caller is the owner (this contract, which deployed c),
        // newOwner must be non-zero for the call to succeed
        vm.assume(newOwner != address(0));

        vm.prank(address(this));
        c.transferOwnership(newOwner);

        // Universal rule: the new owner is exactly the address passed in.
        assertTrue(c.owner() == newOwner);
    }
}
